package state

// adr012V13DDL is the genuine schema at e2b94e3c, captured before ADR-012.
// It deliberately does not reference mutable current-schema declarations.
var adr012V13DDL = []string{
	`CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL)`,
	`CREATE TABLE plans (plan_id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE, repository_id TEXT NOT NULL, created_at INTEGER NOT NULL, payload BLOB NOT NULL)`,
	`CREATE TABLE runs (run_id TEXT PRIMARY KEY, plan_id TEXT NOT NULL UNIQUE, repository_id TEXT NOT NULL, state TEXT NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER, payload BLOB NOT NULL, finalized INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(plan_id) REFERENCES plans(plan_id))`,
	`CREATE TABLE coverage (run_id TEXT NOT NULL, coverage_key TEXT NOT NULL, status TEXT NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(run_id, coverage_key), FOREIGN KEY(run_id) REFERENCES runs(run_id) ON DELETE CASCADE)`,
	`CREATE TABLE observations (observation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, observed_at INTEGER NOT NULL, payload BLOB NOT NULL, FOREIGN KEY(run_id) REFERENCES runs(run_id) ON DELETE RESTRICT)`,
	`CREATE TABLE artifacts (digest TEXT PRIMARY KEY, artifact_id TEXT NOT NULL UNIQUE, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at INTEGER NOT NULL)`,
	`CREATE TABLE issues (issue_id TEXT PRIMARY KEY, state TEXT NOT NULL, updated_at INTEGER NOT NULL, payload BLOB NOT NULL)`,
	`CREATE TABLE issue_observations (issue_id TEXT NOT NULL, observation_id TEXT NOT NULL, PRIMARY KEY(issue_id, observation_id), FOREIGN KEY(issue_id) REFERENCES issues(issue_id) ON DELETE CASCADE, FOREIGN KEY(observation_id) REFERENCES observations(observation_id) ON DELETE RESTRICT)`,
	`CREATE TABLE issue_history (issue_id TEXT NOT NULL, ordinal INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(issue_id, ordinal), FOREIGN KEY(issue_id) REFERENCES issues(issue_id) ON DELETE CASCADE)`,
	`CREATE TABLE inventory_snapshots (run_id TEXT PRIMARY KEY, payload BLOB NOT NULL, FOREIGN KEY(run_id) REFERENCES runs(run_id))`,
	`CREATE TABLE run_job_commits (run_id TEXT NOT NULL, job_id TEXT NOT NULL, committed_at INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(run_id, job_id), FOREIGN KEY(run_id) REFERENCES runs(run_id) ON DELETE CASCADE)`,
	`CREATE INDEX coverage_success_lookup ON coverage(coverage_key, status, run_id)`,
	`CREATE INDEX runs_success_lookup ON runs(state, finished_at DESC)`,
	`CREATE INDEX observations_by_run ON observations(run_id, observed_at)`,
	`CREATE INDEX issues_by_state ON issues(state, updated_at DESC)`,
	`CREATE INDEX run_job_commits_by_run ON run_job_commits(run_id, committed_at, job_id)`,
	`CREATE TABLE plan_jobs (plan_id TEXT NOT NULL, run_id TEXT NOT NULL, job_id TEXT NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(plan_id, job_id), FOREIGN KEY(plan_id) REFERENCES plans(plan_id))`,
	`CREATE TABLE issue_migration_ambiguities (issue_id TEXT PRIMARY KEY, legacy_id TEXT NOT NULL, reason TEXT NOT NULL)`,
	`CREATE TABLE IF NOT EXISTS would_block (id TEXT PRIMARY KEY, head_revision TEXT NOT NULL, base_revision TEXT NOT NULL, issue_id TEXT NOT NULL, check_id TEXT NOT NULL, rule_version TEXT NOT NULL, path TEXT NOT NULL, attribution TEXT NOT NULL, profile TEXT NOT NULL, triage TEXT NOT NULL DEFAULT 'undecided', triage_actor TEXT NOT NULL DEFAULT '', triage_reason TEXT NOT NULL DEFAULT '', recorded_at INTEGER NOT NULL, triaged_at INTEGER)`,
	`CREATE INDEX IF NOT EXISTS would_block_by_check ON would_block(check_id, recorded_at)`,
	`CREATE TABLE IF NOT EXISTS signals (seq INTEGER PRIMARY KEY AUTOINCREMENT, metric TEXT NOT NULL, scope_kind TEXT NOT NULL, scope_anchor TEXT NOT NULL, snapshot TEXT NOT NULL, window TEXT NOT NULL, tool_digest TEXT NOT NULL, config_digest TEXT NOT NULL, payload BLOB NOT NULL, UNIQUE(metric, scope_kind, scope_anchor, snapshot, window, tool_digest, config_digest))`,
	`CREATE INDEX IF NOT EXISTS signals_by_scope ON signals(scope_anchor, metric, seq)`,
	`CREATE TABLE IF NOT EXISTS annotations (annotation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, issue_id TEXT NOT NULL, unit_key TEXT NOT NULL, question_version TEXT NOT NULL, stale INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, payload BLOB NOT NULL)`,
	`CREATE INDEX IF NOT EXISTS annotations_by_issue ON annotations(issue_id, created_at, annotation_id)`,
	`CREATE TABLE IF NOT EXISTS ranking_records (run_id TEXT NOT NULL, issue_id TEXT NOT NULL, mode TEXT NOT NULL, created_at INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(run_id, issue_id))`,
	`CREATE INDEX IF NOT EXISTS ranking_records_by_issue ON ranking_records(issue_id, created_at)`,
	`CREATE TABLE IF NOT EXISTS audit_draws (issue_id TEXT NOT NULL, formula_version TEXT NOT NULL, sampler_version TEXT NOT NULL, run_id TEXT NOT NULL, drawn INTEGER NOT NULL, inclusion_probability REAL NOT NULL, created_at INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(issue_id, formula_version, sampler_version))`,
	`CREATE TABLE IF NOT EXISTS disposition_contexts (id INTEGER PRIMARY KEY AUTOINCREMENT, issue_id TEXT NOT NULL, at INTEGER NOT NULL, view TEXT NOT NULL, annotation_visible INTEGER NOT NULL, rank_formula_version TEXT NOT NULL, baseline_version TEXT NOT NULL)`,
	`CREATE INDEX IF NOT EXISTS disposition_contexts_by_issue ON disposition_contexts(issue_id, id)`,
	`CREATE TABLE IF NOT EXISTS ingested_artifacts (snapshot TEXT NOT NULL, digest TEXT NOT NULL, kind TEXT NOT NULL, revision TEXT NOT NULL, producer TEXT NOT NULL, source TEXT NOT NULL, revision_match TEXT NOT NULL, reason TEXT NOT NULL, ingested_at INTEGER NOT NULL, payload BLOB NOT NULL, PRIMARY KEY(snapshot, digest))`,
	`CREATE INDEX IF NOT EXISTS ingested_artifacts_by_snapshot ON ingested_artifacts(snapshot, kind)`,
	`CREATE TABLE IF NOT EXISTS pr_metadata_sources (seq INTEGER PRIMARY KEY AUTOINCREMENT, snapshot TEXT NOT NULL, kind TEXT NOT NULL, origin TEXT NOT NULL, digest TEXT NOT NULL, fetched_at TEXT NOT NULL, prs INTEGER NOT NULL, UNIQUE(snapshot, digest))`,
	`CREATE TABLE IF NOT EXISTS areas (area_id TEXT PRIMARY KEY, payload BLOB NOT NULL)`,
	`CREATE TABLE IF NOT EXISTS associations (id TEXT PRIMARY KEY, run_id TEXT NOT NULL, decided_at INTEGER NOT NULL, refresh_generation TEXT NOT NULL, payload BLOB NOT NULL)`,
	`CREATE INDEX IF NOT EXISTS associations_by_decision ON associations(decided_at, id)`,
	`CREATE INDEX IF NOT EXISTS associations_by_generation ON associations(refresh_generation, decided_at, id)`,
	`CREATE INDEX IF NOT EXISTS associations_by_run ON associations(run_id)`,
}
